import 'reflect-metadata';
import assert from 'node:assert/strict';
import test from 'node:test';
import { Test } from '@nestjs/testing';
import { CartService } from '../src/nest-cart.mjs';

test('Nest testing module resolves the real injectable cart service', async () => {
  const moduleRef = await Test.createTestingModule({ providers: [CartService] }).compile();
  const service = moduleRef.get(CartService);
  const prices = new Map([['lamp', 4950], ['desk', 49900]]);
  assert.deepEqual(service.quote([{ productId: 'lamp', quantity: 2, priceCents: 1 }], prices), { subtotalCents: 9900, taxCents: 990, totalCents: 10890 });
  assert.throws(() => service.quote([{ productId: 'missing', quantity: 1 }], prices), /unknown|not found/i);
  assert.throws(() => service.quote([{ productId: 'lamp', quantity: 0 }], prices), /quantity/i);
  await moduleRef.close();
});

import { Injectable } from '@nestjs/common';

export class CartService {
  quote(lines, prices) {
    throw new Error('TODO quote');
  }
}

Injectable()(CartService);
